'use strict';

// MODULES //

var isNonNegativeInteger = require( '@stdlib/assert/is-nonnegative-integer' ).isPrimitive;
var isArrayBuffer = require( '@stdlib/assert/is-arraybuffer' );
var isDataType = require( '@stdlib/ndarray/base/assert/is-data-type' );
var objectAssign = require( '@stdlib/object/assign' );
var format = require( '@stdlib/string/format' );
var validate = require( './validate.js' );
var main = require( './main.js' );


// MAIN //

/**
* Returns a function for creating a zero-dimensional ndarray.
*
* @param {*} dtype - data type
* @param {Options} [options] - function options
* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray by default
* @param {string} [options.order='row-major'] - default memory layout (either row-major or column-major)
* @throws {TypeError} first argument must be a supported data type
* @throws {TypeError} options argument must be an object
* @throws {TypeError} must provide valid options
* @returns {Function} function for creating a zero-dimensional ndarray
*
* @example
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var Float32Tensor0D = factory( 'float32' );
*
* var arr = new Float32Tensor0D( 1.0 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var Float32Tensor0D = factory( 'float32' );
*
* var buf = new ArrayBuffer( 4 );
* var arr = new Float32Tensor0D( buf );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*
* @example
* var ArrayBuffer = require( '@stdlib/array/buffer' );
* var getDType = require( '@stdlib/ndarray/dtype' );
*
* var Float32Tensor0D = factory( 'float32' );
*
* var buf = new ArrayBuffer( 8 );
* var arr = new Float32Tensor0D( buf, 4 );
* // returns <ndarray>
*
* var dt = String( getDType( arr ) );
* // returns 'float32'
*/
function factory( dtype, options ) {
	var opts;
	var err;
	if ( !isDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a supported data type. Value: `%s`.', dtype ) );
	}
	opts = {};
	if ( arguments.length > 1 ) {
		err = validate( opts, options );
		if ( err ) {
			throw err;
		}
	}
	return tensor0d;

	/**
	* Creates a zero-dimensional ndarray.
	*
	* @private
	* @param {(ArrayBuffer|*)} [arg] - scalar or buffer
	* @param {NonNegativeInteger} [byteOffset=0] - byte offset
	* @param {Options} [options] - function options
	* @param {boolean} [options.readonly] - boolean indicating whether to return a read-only ndarray
	* @param {string} [options.order] - memory layout (either row-major or column-major)
	* @throws {Error} unexpected error
	* @returns {ndarray} zero-dimensional ndarray
	*/
	function tensor0d() {
		var options;
		var nargs;
		var arg0;
		var arg1;
		var err;

		options = objectAssign( {}, opts );
		nargs = arguments.length;

		// Case: tensor0d()
		if ( nargs === 0 ) {
			return main( dtype, options );
		}
		// Case: tensor0d( ArrayBuffer, byteOffset, options )
		if ( nargs > 2 ) {
			err = validate( options, arguments[ 2 ] );
			if ( err ) {
				throw err;
			}
			return main( arguments[ 0 ], arguments[ 1 ], dtype, options );
		}
		// Case: tensor0d( arg0, arg1 )
		if ( nargs === 2 ) {
			arg0 = arguments[ 0 ];
			arg1 = arguments[ 1 ];

			// Case: tensor0d( ArrayBuffer, arg1 )
			if ( isArrayBuffer( arg0 ) ) {
				// Case: tensor0d( ArrayBuffer, byteOffset )
				if ( isNonNegativeInteger( arg1 ) ) {
					return main( arg0, arg1, dtype, options );
				}
				// Case: tensor0d( ArrayBuffer, options )
				err = validate( options, arg1 );
				if ( err ) {
					throw err;
				}
				return main( arg0, dtype, options );
			}
			// Case: tensor0d( scalar, options )
			err = validate( options, arg1 );
			if ( err ) {
				throw err;
			}
			return main( arg0, dtype, options );
		}
		// nargs === 1

		// Case: tensor0d( ArrayBuffer|scalar ) => note: we cannot disambiguate `tensor0d( {} )` where `{}` is a "scalar" versus when `{}` is an options object, so we simply assume that, when provided a single argument which is NOT an `ArrayBuffer`, the user is always providing a "scalar". This creates what could be considered a minor ergonomic inconvenience if a user wants an uninitialized zero-dimensional ndarray with a specific memory layout, as they need to provide an explicit scalar value, e.g., `new Float32Tensor0D( <scalar>, options )`, but this should be a rare enough use case, while `new Float32Tensor0D( <scalar> )` is assumed to be a dominant use case. Similarly, in the (very) rare case where a user wants to provide an `ArrayBuffer` as a "scalar", this would not be possible, as we always treat an `ArrayBuffer` argument as the underlying memory of the returned ndarray. In principle, we could use the dtype and try to match the scalar type with the dtype, and, in the event of a mismatch, fallback to assuming an options object, but this does not generalize when the dtype is "generic". So, rather than have diverging behaviors, seems best to be consistent across constructors...
		return main( arguments[ 0 ], dtype, options );
	}
}


// EXPORTS //

module.exports = factory;
